// ========== КЛЮЧЕВЫЕ ПРИЗНАКИ ==========
// ЭЛЕМЕНТ (характеристика атома/вхождение в соединения):
//   - Атомная масса, заряд ядра, число протонов/электронов, изотопы
//   - Степень окисления, валентность, валентные электроны
//   - Электроотрицательность, положение в ПС (период, группа, семейство)
//   - Распространённость в земной коре (в виде соединений/минералов)
//   - Входит в состав минералов, соединений, кислот, оксидов, солей
//   - Входит в состав биомолекул (белков, ДНК, гемоглобина, витаминов)
//   - Входит в состав живых организмов (в виде ионов/соединений)
//   - Необходим растениям/организмам (в виде соединений)
//
// ПРОСТОЕ ВЕЩЕСТВО (свойства молекулы/кристалла):
//   - Цвет, запах, агрегатное состояние, плотность, Tпл/Tкип
//   - Физические свойства (металл/неметалл, проводимость, ковкость)
//   - Аллотропные модификации (это простые вещества!)
//   - Получение вещества (электролиз, восстановление, перегонка)
//   - Применение в промышленности (сплавы, катализатор, заполнение ламп)
//   - Химические реакции (горение, окисление, реакции с другими веществами)
//   - Токсичность, взрывоопасность, воспламеняемость
//   - Свободное состояние в природе

if (typeof module !== 'undefined' && module.exports) {
  module.exports = IQMO_CAT01_QUESTIONS;
}

// Браузерный режим: конвертируем и добавляем в общий банк.
(function () {
	if (typeof window === 'undefined') return;
	if (!Array.isArray(IQMO_CAT01_QUESTIONS)) return;

	function isPick2(q) {
		return /Выберите\s+(два|две)\b/i.test(q && q.question ? q.question : '');
	}

	function toHtml(s) {
		return String(s || '')
			.replace(/&/g, '&amp;')
			.replace(/</g, '&lt;')
			.replace(/>/g, '&gt;');
	}

	function normalizeOne(src, idx) {
		var id = 10001 + idx;
		var pick2 = isPick2(src);
		var rawAnswer = String(src.answer || '');
		var options = Array.isArray(src.options)
			? src.options.map(function (label, i) {
					return { id: String(i + 1), label: String(label) };
				})
			: [];

		var out = {
			id: id,
			type: pick2 ? 'multi' : 'single',
			title: 'Категория 01 · Задание',
			body: '<p>' + toHtml(src.question) + '</p>',
			options: options,
			explanation: String(src.explanation || '')
		};

		if (pick2) {
			out.pickCount = 2;
			out.correct = rawAnswer.split('').filter(Boolean);
		} else {
			out.correct = rawAnswer;
		}

		return out;
	}

	var converted = IQMO_CAT01_QUESTIONS.map(normalizeOne);
	window.CHEMISTRY_QUESTIONS = window.CHEMISTRY_QUESTIONS || [];
	for (var i = 0; i < converted.length; i++) window.CHEMISTRY_QUESTIONS.push(converted[i]);
})();

;

