// ========== СТАТИСТИКА ==========
// Тема 38 (Задания для подготовки): 35 вопросов
//   ID: 10718-10737, 11004, 21417, 21441, 21474, 21499, 21523, 21662,
//       22631, 22655, 22678, 22702, 22725, 22750, 22774, 22797
// Тема 82 (Открытый банк ФИПИ): 30 вопросов
//   ID: 20378-20407 (последовательные)
// ВСЕГО: 65 вопросов типа 3 (упорядочивание химических элементов)

// ========== ОСНОВНЫЕ ЗАКОНОМЕРНОСТИ В ПЕРИОДИЧЕСКОЙ СИСТЕМЕ ==========
//
// ПО ПЕРИОДУ (слева направо):
//   ↑ Заряд ядра, число электронов, валентных электронов
//   ↑ Высшая степень окисления, номер группы
//   ↑ Электроотрицательность
//   ↑ Неметаллические свойства, окислительные свойства
//   ↑ Кислотные свойства высших оксидов и гидроксидов
//   ↓ Атомный радиус
//   ↓ Металлические свойства, восстановительные свойства
//   ↓ Основные свойства высших оксидов и гидроксидов
//   ↓ Валентность в летучем водородном соединении (8 − № группы)
//
// ПО ГЛАВНОЙ ПОДГРУППЕ (сверху вниз):
//   ↑ Число энергетических уровней (= номер периода)
//   ↑ Атомный радиус
//   ↑ Металлические свойства, восстановительные свойства
//   ↑ Основные свойства высших оксидов
//   ↑ Кислотность летучих водородных соединений (HF < HCl < HBr < HI)
//   ↓ Электроотрицательность
//   ↓ Неметаллические свойства, окислительные свойства
//   ↓ Кислотные свойства высших оксидов
//
// ТИПЫ ВЫСШИХ ОКСИДОВ В 3-М ПЕРИОДЕ:
//   Na2O, MgO — основные
//   Al2O3 — амфотерный
//   SiO2, P2O5, SO3, Cl2O7 — кислотные

if (typeof module !== 'undefined' && module.exports) {
  module.exports = IQMO_CAT03_QUESTIONS;
}

// Браузерный режим: конвертируем и добавляем в общий банк.
(function () {
	if (typeof window === 'undefined') return;
	if (!Array.isArray(IQMO_CAT03_QUESTIONS)) return;

	function toHtml(s) {
		return String(s || '')
			.replace(/&/g, '&amp;')
			.replace(/</g, '&lt;')
			.replace(/>/g, '&gt;');
	}

	function normalizeOne(src, idx) {
		// Категория 03: диапазон 30001–30065 (по количеству вопросов)
		var id = 30001 + idx;
		var rawAnswer = String(src.answer || '');

		return {
			id: id,
			type: 'input',
			title: 'Категория 03 · Порядок элементов',
			body: '<p>' + toHtml(src.question) + '</p>',
			placeholder: 'например: 231',
			correct: rawAnswer,
			explanation: String(src.explanation || '')
		};
	}

	var converted = IQMO_CAT03_QUESTIONS.map(normalizeOne);
	window.CHEMISTRY_QUESTIONS = window.CHEMISTRY_QUESTIONS || [];
	for (var i = 0; i < converted.length; i++) window.CHEMISTRY_QUESTIONS.push(converted[i]);
})();

;

