// ========== ОБОБЩЁННЫЕ ПРАВИЛА ==========
// Для определения типа связи в веществе:
// 1. Если вещество — металл (Na, Ca, Fe...) → МЕТАЛЛИЧЕСКАЯ связь
// 2. Если вещество — простое из неметалла (H2, O2, N2, Cl2, S8, P4, алмаз...) → КОВАЛЕНТНАЯ НЕПОЛЯРНАЯ
// 3. Если вещество состоит из разных неметаллов (H2O, NH3, CO2, HCl, H2SO4...) → КОВАЛЕНТНАЯ ПОЛЯРНАЯ
// 4. Если вещество содержит металл + неметалл (NaCl, CaO, K2S...) → ИОННАЯ
// 5. Если вещество содержит NH4+ (соли аммония: NH4Cl, (NH4)2SO4...) → ИОННАЯ
// 6. Соли со сложными анионами (K2SO4, Na2CO3...) содержат ОБА типа связи: ионную + ковалентную полярную
// 7. Водородная связь — МЕЖДУ МОЛЕКУЛАМИ с H, связанным с F, O или N
//
// ТИПЫ СВЯЗЕЙ ПО КРАТНОСТИ:
// Одинарная: H2 (H-H), HCl (H-Cl), NH3 (N-H), H2O (O-H), CH4 (C-H)
// Двойная: O2 (O=O), CO2 (O=C=O), SO2, C2H4 (этилен)
// Тройная: N2 (N≡N), C2H2 (ацетилен)

if (typeof module !== 'undefined' && module.exports) {
  module.exports = IQMO_CAT04_QUESTIONS;
}

// Браузерный режим: конвертируем и добавляем в общий банк.
(function () {
	if (typeof window === 'undefined') return;
	if (!Array.isArray(IQMO_CAT04_QUESTIONS)) return;

	function isPick2(q) {
		return /Выберите\s+(два|две)\b/i.test(q && q.question ? q.question : '');
	}

	function toHtml(s) {
		return String(s || '')
			.replace(/&/g, '&amp;')
			.replace(/</g, '&lt;')
			.replace(/>/g, '&gt;');
	}

	function normalizeOne(src, idx) {
		// Категория 04: диапазон 40001–400XX (по количеству вопросов)
		var id = 40001 + idx;
		var pick2 = isPick2(src);
		var rawAnswer = String(src.answer || '');
		var options = Array.isArray(src.options)
			? src.options.map(function (label, i) {
					return { id: String(i + 1), label: String(label) };
				})
			: [];

		var out = {
			id: id,
			type: pick2 ? 'multi' : 'single',
			title: 'Категория 04 · Химическая связь',
			body: '<p>' + toHtml(src.question) + '</p>',
			options: options,
			explanation: String(src.explanation || '')
		};

		if (pick2) {
			out.pickCount = 2;
			out.correct = rawAnswer.split('').filter(Boolean);
		} else {
			out.correct = rawAnswer;
		}

		return out;
	}

	var converted = IQMO_CAT04_QUESTIONS.map(normalizeOne);
	window.CHEMISTRY_QUESTIONS = window.CHEMISTRY_QUESTIONS || [];
	for (var i = 0; i < converted.length; i++) window.CHEMISTRY_QUESTIONS.push(converted[i]);
})();

;

