// Тема 27 "Задания для подготовки": 37 задач с текстовыми вариантами (из 44)
//   Включено: 258, 1044, 5851-5868, 6417, 6441, 6465, 6564, 6595,
//             10451, 10475, 10499, 10523, 19170, 21477, 21502, 21665, 22634, 22682, 22706
//   Исключены (SVG-ряды элементов): задачи 31, 32, 35, 38, 39, 41, 42 (7 SVG-задач)
// Тема 46 "Задания прошлых лет": 2 задачи (9363, 9388)
// Тема 85 "Открытый банк ФИПИ": 25 задач (20608-20632)
// ВСЕГО в файле: 64 задания типа 6

// ========== ОБОБЩЁННЫЕ ПРАВИЛА ==========
// СТРОЕНИЕ АТОМА:
// • Номер периода = число электронных слоёв (энергетических уровней)
// • Номер группы (A) = число валентных электронов (для A-групп)
// • Порядковый номер = число протонов = число электронов
// • Массовое число = протоны + нейтроны
//
// ЗАКОНОМЕРНОСТИ В ПЕРИОДЕ (слева направо):
// • ↑ число протонов, электронов, ВЭ
// • ↑ электроотрицательность, неметаллические свойства
// • ↓ радиус атома, металлические свойства
// • Оксиды: от основных → через амфотерные → к кислотным
//
// ЗАКОНОМЕРНОСТИ В ГРУППЕ (сверху вниз):
// • ↑ число электронных слоёв, радиус атома
// • ↑ металлические свойства, основные свойства оксидов
// • ↓ электроотрицательность, неметаллические свойства
//
// ТИПЫ ЭЛЕМЕНТОВ:
// • s-элементы: IA, IIA группы (H, He, Li, Be, Na, Mg, K, Ca...)
// • p-элементы: IIIA-VIIIA группы (B, C, N, O, F, Al, Si...)
// • d-элементы: побочные подгруппы (Sc, Ti, V, Cr, Fe, Cu, Zn...)
//
// ГРУППЫ ЭЛЕМЕНТОВ:
// • Щелочные металлы: Li, Na, K, Rb, Cs (IA)
// • Щёлочноземельные металлы: Ca, Sr, Ba, Ra (IIA)
// • Халькогены: O, S, Se, Te (VIA)
// • Галогены: F, Cl, Br, I (VIIA)
// • Инертные газы: He, Ne, Ar, Kr, Xe (VIIIA)

if (typeof module !== 'undefined' && module.exports) {
  module.exports = IQMO_CAT05_QUESTIONS;
}

// Браузерный режим: конвертируем и добавляем в общий банк.
(function () {
	if (typeof window === 'undefined') return;
	if (!Array.isArray(IQMO_CAT05_QUESTIONS)) return;

	function isPick2(q) {
		return /Какие\s+два\s+утверждения/i.test(q && q.question ? q.question : '')
			|| /Выберите\s+(два|две)\b/i.test(q && q.question ? q.question : '');
	}

	function toHtml(s) {
		return String(s || '')
			.replace(/&/g, '&amp;')
			.replace(/</g, '&lt;')
			.replace(/>/g, '&gt;');
	}

	function normalizeOne(src, idx) {
		// Категория 05: диапазон 50001–50064 (в файле 64 задания)
		var id = 50001 + idx;
		var pick2 = isPick2(src);
		var rawAnswer = String(src.answer || '');
		var options = Array.isArray(src.options)
			? src.options.map(function (label, i) {
					return { id: String(i + 1), label: String(label) };
				})
			: [];

		var out = {
			id: id,
			type: pick2 ? 'multi' : 'single',
			title: 'Категория 05 · Электронные оболочки',
			body: '<p>' + toHtml(src.question) + '</p>',
			options: options,
			explanation: String(src.explanation || '')
		};

		if (pick2) {
			out.pickCount = 2;
			out.correct = rawAnswer.split('').filter(Boolean);
		} else {
			out.correct = rawAnswer;
		}

		return out;
	}

	var converted = IQMO_CAT05_QUESTIONS.map(normalizeOne);
	window.CHEMISTRY_QUESTIONS = window.CHEMISTRY_QUESTIONS || [];
	for (var i = 0; i < converted.length; i++) window.CHEMISTRY_QUESTIONS.push(converted[i]);
})();

;

