//                          10852, 10853, 10856, 10858, 10859, 10875, 10876,
//                          10877, 10878, 10881, 10883, 10886, 10887, 10889,
//                          10890, 10891
// Исключены 45 задач из-за того, что на сайте видно только первый вариант
// ответа (SVG с химической формулой), а варианты 2–5 недоступны.
// ВСЕГО в файле: 23 задания типа 8

// ========== ПАМЯТКА ПО ОКСИДАМ ==========
//
// ОСНОВНЫЕ ОКСИДЫ (реагируют с кислотами, кислотными оксидами, водой*):
// Na2O, K2O, Li2O, Rb2O, Cs2O — оксиды щелочных металлов;
// MgO, CaO, SrO, BaO — оксиды щелочноземельных металлов;
// CuO, FeO, NiO, MnO — оксиды d-металлов в низких СО.
// * Только оксиды щелочных и щелочноземельных металлов реагируют с H2O.
//
// КИСЛОТНЫЕ ОКСИДЫ (реагируют с основаниями, основными оксидами, водой):
// CO2, CO (CO несолеобразующий!), SO2, SO3, NO2, N2O3, N2O5, P2O3, P2O5,
// SiO2 (с водой не реагирует!), B2O3, Cl2O, Cl2O7, Mn2O7, CrO3.
//
// АМФОТЕРНЫЕ ОКСИДЫ (реагируют с кислотами И щелочами):
// BeO, ZnO, Al2O3, Cr2O3, Fe2O3, SnO, SnO2, PbO, PbO2, MnO2.
//
// НЕСОЛЕОБРАЗУЮЩИЕ ОКСИДЫ (не реагируют с кислотами и основаниями):
// CO, NO, N2O, SiO.
//
// КАЧЕСТВЕННЫЕ РЕАКЦИИ НА ГАЗООБРАЗНЫЕ ОКСИДЫ:
// • CO2 — помутнение известковой воды (Ca(OH)2 → CaCO3↓).
// • SO2 — обесцвечивание раствора KMnO4 или фуксина.
// • NO2 — бурый цвет газа, специфический запах.
// • NH3 (оксид не является, но часто в тестах) — синеет влажная лакмусовая бумажка.
//
// ВАЖНЫЕ ИСКЛЮЧЕНИЯ:
// • SiO2 не реагирует с кислотами (кроме HF): SiO2 + 4HF → SiF4↑ + 2H2O.
// • CO (угарный газ) — несолеобразующий, но является восстановителем:
//     CO + CuO → Cu + CO2; 3CO + Fe2O3 → 2Fe + 3CO2.
// • Оксиды металлов в высших степенях окисления (Cr2O3, Mn2O7) — кислотные,
//   не основные.
// • Fe2O3 — амфотерный (!), а FeO — основный (разный характер при разных СО).

if (typeof module !== 'undefined' && module.exports) {
  module.exports = IQMO_CAT07_QUESTIONS;
}

// Браузерный режим: конвертируем и добавляем в общий банк.
(function () {
	if (typeof window === 'undefined') return;
	if (!Array.isArray(IQMO_CAT07_QUESTIONS)) return;

	function toHtml(s) {
		return String(s || '')
			.replace(/&/g, '&amp;')
			.replace(/</g, '&lt;')
			.replace(/>/g, '&gt;');
	}

	function normalizeOne(src, idx) {
		var id = 70001 + idx;
		var rawAnswer = String(src.answer || '');
		var options = Array.isArray(src.options)
			? src.options.map(function (label, i) {
					return { id: String(i + 1), label: String(label) };
				})
			: [];

		return {
			id: id,
			type: 'multi',
			pickCount: 2,
			title: 'Категория 07 · Простые вещества и оксиды',
			body: '<p>' + toHtml(src.question) + '</p>',
			options: options,
			correct: rawAnswer.split('').filter(Boolean),
			explanation: String(src.explanation || '')
		};
	}

	var converted = IQMO_CAT07_QUESTIONS.map(normalizeOne);
	window.CHEMISTRY_QUESTIONS = window.CHEMISTRY_QUESTIONS || [];
	for (var i = 0; i < converted.length; i++) window.CHEMISTRY_QUESTIONS.push(converted[i]);
})();

;

