(function () {
	if (typeof window === 'undefined') return;
	if (!Array.isArray(IQMO_CAT11_QUESTIONS)) return;

	function toHtml(s) {
		return String(s || '')
			.replace(/&/g, '&amp;')
			.replace(/</g, '&lt;')
			.replace(/>/g, '&gt;')
			.replace(/\n/g, '<br>');
	}

	function parsePairs(question) {
		var q = String(question || '');
		var mA = q.match(/(^|\n)\s*А\)\s*([^\n]+)/);
		var mB = q.match(/(^|\n)\s*Б\)\s*([^\n]+)/);
		var mV = q.match(/(^|\n)\s*В\)\s*([^\n]+)/);
		if (!mA || !mB || !mV) return null;
		return [mA[2].trim(), mB[2].trim(), mV[2].trim()];
	}

	function normalizeOne(src, idx) {
		var id = 94001 + idx;
		var pairs = parsePairs(src.question);
		var right = Array.isArray(src.options)
			? src.options.map(function (label, i) {
					return { id: String(i + 1), label: toHtml(label) };
				})
			: [];
		var ans = String(src.answer || '').replace(/\D/g, '');
		var correct = ans.split('').filter(Boolean);

		if (!pairs || right.length < 2 || correct.length !== 3) {
			return {
				id: id,
				type: 'input',
				title: 'Категория 11 · Условия и признаки реакций',
				body: '<p>' + toHtml(src.question) + '</p>',
				placeholder: 'например, 421',
				correct: String(src.answer || ''),
				explanation: String(src.explanation || '')
			};
		}

		return {
			id: id,
			type: 'match',
			title: 'Категория 11 · Условия и признаки реакций',
			body: '<p>' + toHtml(src.question) + '</p>',
			matchLeft: [
				{ letter: 'А', label: toHtml(pairs[0]) },
				{ letter: 'Б', label: toHtml(pairs[1]) },
				{ letter: 'В', label: toHtml(pairs[2]) }
			],
			matchRight: right,
			correct: correct,
			explanation: String(src.explanation || '')
		};
	}

	var converted = IQMO_CAT11_QUESTIONS.map(normalizeOne);
	window.CHEMISTRY_QUESTIONS = window.CHEMISTRY_QUESTIONS || [];
	for (var i = 0; i < converted.length; i++) window.CHEMISTRY_QUESTIONS.push(converted[i]);
})();

;

