//   Исключены (SVG-формулы в вариантах): 204, 226, 336, 358, 446, 537, 562,
//     609, 631, 653, 843, 865, 899, 921, 943, 965, 1203, 1225, 1252, 2190,
//     2220, 2235, 2323, 2378, 2446, 2579, 2624, 2674, 2719, 2722, 3105, 3120,
//     3148, 3220, 3346, 3721, 3725, 3758, 4567, 4613, 4717 (41 SVG-задача)
// Тема 49 "Задания прошлых лет": 3 задачи с текстовыми вариантами (из 11)
//   Включены ID: 9369, 9394, 21551
//   Исключены (SVG-уравнения): 28, 50, 72, 94, 116, 138, 160, 182 (8 SVG-задач)
// ВСЕГО в файле: 36 заданий типа 11

// ========== ОБОБЩЁННЫЕ ПРАВИЛА ==========
// 
// КАК ОПРЕДЕЛИТЬ ТИП РЕАКЦИИ:
// 1. Если одно вещество → несколько → РАЗЛОЖЕНИЕ
// 2. Если несколько веществ → одно → СОЕДИНЕНИЕ
// 3. Если простое + сложное → простое + сложное → ЗАМЕЩЕНИЕ
// 4. Если сложное + сложное → сложное + сложное → ОБМЕН
//
// КАК ОПРЕДЕЛИТЬ ОВР:
// • Если участвует простое вещество (кроме обмена) — почти всегда ОВР
// • Все реакции замещения — ОВР
// • Реакции обмена (в растворах, нейтрализация, осаждение) — НЕ ОВР
// • Проверяй степени окисления: если они меняются — ОВР
//
// КЛЮЧЕВЫЕ ПРИЗНАКИ ДЛЯ КОНКРЕТНЫХ РЕАКЦИЙ:
// • AgNO3 + Cl⁻ → AgCl↓ (белый творожистый осадок)
// • Cu²⁺ + OH⁻ → Cu(OH)2↓ (голубой осадок)
// • Fe³⁺ + OH⁻ → Fe(OH)3↓ (бурый осадок)
// • Активный металл + кислота → соль + H2↑
// • Карбонат + кислота → соль + H2O + CO2↑
// • CuO (чёрный) + H2 → Cu (красный) + H2O (изменение цвета)
// • Нейтрализация: кислота + основание → соль + вода (без внешних признаков)
//
// ФИЗИЧЕСКИЕ ЯВЛЕНИЯ (НЕ химические):
// • Плавление, кипение, испарение, замерзание, конденсация
// • Возгонка (сублимация)
// • Измельчение, растворение (в большинстве случаев)
// • Образование росы, инея, льда, тумана
// • Диффузия (распространение запаха)

if (typeof module !== 'undefined' && module.exports) {
  module.exports = IQMO_CAT10_QUESTIONS;
}

// Браузерный режим: конвертируем и добавляем в общий банк.
(function () {
	if (typeof window === 'undefined') return;
	if (!Array.isArray(IQMO_CAT10_QUESTIONS)) return;

	function isPick2(q) {
		return /Выберите\s+(два|две)\b/i.test(q && q.question ? q.question : '');
	}

	function toHtml(s) {
		return String(s || '')
			.replace(/&/g, '&amp;')
			.replace(/</g, '&lt;')
			.replace(/>/g, '&gt;');
	}

	function normalizeOne(src, idx) {
		// Категория 10: диапазон 100001–100036 (в файле 36 заданий)
		var id = 100001 + idx;
		var pick2 = isPick2(src);
		var rawAnswer = String(src.answer || '');
		var options = Array.isArray(src.options)
			? src.options.map(function (label, i) {
					return { id: String(i + 1), label: String(label) };
				})
			: [];

		var out = {
			id: id,
			type: pick2 ? 'multi' : 'single',
			title: 'Категория 10 · Реакции и уравнения',
			body: '<p>' + toHtml(src.question) + '</p>',
			options: options,
			explanation: String(src.explanation || '')
		};

		if (pick2) {
			out.pickCount = 2;
			out.correct = rawAnswer.split('').filter(Boolean);
		} else {
			out.correct = rawAnswer;
		}

		return out;
	}

	var converted = IQMO_CAT10_QUESTIONS.map(normalizeOne);
	window.CHEMISTRY_QUESTIONS = window.CHEMISTRY_QUESTIONS || [];
	for (var i = 0; i < converted.length; i++) window.CHEMISTRY_QUESTIONS.push(converted[i]);
})();

;

