if (typeof module !== 'undefined' && module.exports) {
	module.exports = IQMO_CAT16_QUESTIONS;
}

(function () {
	if (typeof window === 'undefined') return;
	if (!Array.isArray(IQMO_CAT16_QUESTIONS)) return;

	function toHtml(s) {
		return String(s || '')
			.replace(/&/g, '&amp;')
			.replace(/</g, '&lt;')
			.replace(/>/g, '&gt;')
			.replace(/\n/g, '<br>');
	}

	function parseLeft(question) {
		// Вытаскиваем три строки «А) ...», «Б) ...», «В) ...»
		var q = String(question || '').replace(/\r/g, '');
		var mA = q.match(/(^|\n)\s*А\)\s*([^\n]+)/);
		var mB = q.match(/(^|\n)\s*Б\)\s*([^\n]+)/);
		var mV = q.match(/(^|\n)\s*В\)\s*([^\n]+)/);
		if (!mA || !mB || !mV) return null;
		return [mA[2].trim(), mB[2].trim(), mV[2].trim()];
	}

	function normalizeOne(src, idx) {
		var id = 98001 + idx;
		var left = parseLeft(src.question);
		var right = [];
		// Правые варианты чаще всего в тексте «1) ...» и т.п., но в файле они уже есть внутри question.
		// Для UI берём варианты из options, иначе показываем 1..4.
		if (Array.isArray(src.options) && src.options.length) {
			right = src.options.map(function (label, i) {
				return { id: String(i + 1), label: toHtml(label) };
			});
		} else {
			for (var i = 1; i <= 4; i++) right.push({ id: String(i), label: 'реактив ' + i });
		}

		var ans = String(src.answer || '').replace(/\D/g, '');
		var correct = ans.split('').filter(Boolean);

		if (!left || correct.length !== 3) {
			return {
				id: id,
				type: 'input',
				title: 'Категория 16 · Качественные реакции',
				body: '<p style="white-space: pre-line;">' + toHtml(src.question) + '</p>',
				placeholder: 'например, 241',
				correct: String(src.answer || ''),
				explanation: String(src.explanation || '')
			};
		}

		return {
			id: id,
			type: 'match',
			title: 'Категория 16 · Качественные реакции',
			body: '<p style="white-space: pre-line;">' + toHtml(src.question) + '</p>',
			matchLeft: [
				{ letter: 'А', label: toHtml(left[0]) },
				{ letter: 'Б', label: toHtml(left[1]) },
				{ letter: 'В', label: toHtml(left[2]) }
			],
			matchRight: right,
			correct: correct,
			explanation: String(src.explanation || '')
		};
	}

	var converted = IQMO_CAT16_QUESTIONS.map(normalizeOne);
	window.CHEMISTRY_QUESTIONS = window.CHEMISTRY_QUESTIONS || [];
	for (var k = 0; k < converted.length; k++) window.CHEMISTRY_QUESTIONS.push(converted[k]);
})();
;
